import json,pathlib,html
R=pathlib.Path(__file__).resolve().parent.parent
C=json.loads((R/'source/content.json').read_text())
BASE='https://akisui.github.io/machi-web/'
TF='https://testflight.apple.com/join/vRaaadNM'
icon='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'
langs={'ja':'日本語','zh-Hans':'简体中文','zh-Hant-TW':'正體中文（台灣）','zh-Hant-HK':'繁體中文（香港）','en':'English'}
def esc(s):return html.escape(s)
def lines(s):return esc(s).replace('\n','<br>')
def build(lang,root=False):
 c=C[lang];a='assets/' if root else '../assets/'
 def phone(n,extra=''):
  names=['calendar','wallet','archive','search']
  return f'<div class="phone {extra}"><img src="{a}screens/{lang}-{n:02d}-{names[n-1]}.jpg" width="1320" height="2868" alt="{esc(c[photoAlt]) if False else esc(c["photoAlt"])} — {esc(c["tabs"][n-1])}" loading="lazy" decoding="async"></div>'
 def button():return f'<a class="button" href="{TF}">{esc(c["join"])} {icon}</a>'
 switch=''.join(f'<option value="{k}" {"selected" if k==lang else ""}>{v}</option>' for k,v in langs.items())
 tabs=''.join(f'<button type="button" role="tab" id="screen-tab-{i}" aria-selected="{str(i==0).lower()}" aria-controls="screen-view" tabindex="{0 if i==0 else -1}" data-screen="{i+1:02d}-{n}">{esc(c["tabs"][i])}</button>' for i,n in enumerate(['calendar','wallet','archive','search']))
 faq=''.join(f'<details><summary>{esc(q)}</summary><p>{esc(ans)}</p></details>' for q,ans in c['faq'])
 steps=''.join(f'<div class="step"><span class="step-num">0{i+1}</span><h3>{esc(t)}</h3><p>{esc(d)}</p></div>' for i,(t,d) in enumerate(c['steps']))
 alternates=''.join(f'<link rel="alternate" hreflang="{k}" href="{BASE}{k}/">' for k in langs)
 redirect='''<script>(function(){var s;try{s=localStorage.getItem('machi-site-language')}catch(e){}var all=['ja','zh-Hans','zh-Hant-TW','zh-Hant-HK','en'];var n=(navigator.language||'ja').toLowerCase();var l=all.includes(s)?s:n.startsWith('zh')?(n.includes('hk')||n.includes('mo')?'zh-Hant-HK':n.includes('tw')||n.includes('hant')?'zh-Hant-TW':'zh-Hans'):n.startsWith('en')?'en':'ja';location.replace('./'+l+'/'+location.hash)})();</script>''' if root else ''
 page=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#faf9f6"><title>{esc(c['title'])}</title><meta name="description" content="{esc(c['description'])}"><link rel="icon" href="{a}icon.png"><link rel="apple-touch-icon" href="{a}icon.png"><link rel="canonical" href="{BASE}{lang}/">{alternates}<link rel="alternate" hreflang="x-default" href="{BASE}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(c['title'])}"><meta property="og:description" content="{esc(c['description'])}"><meta property="og:url" content="{BASE}{lang}/"><meta property="og:image" content="{BASE}assets/social-card.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="{a}style.css">{redirect}<script defer src="{a}site.js"></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'SoftwareApplication','name':'まち','alternateName':'machi','operatingSystem':'iOS 17.0 or later','applicationCategory':'LifestyleApplication','description':c['description'],'url':BASE+lang+'/','downloadUrl':TF,'softwareVersion':'1.0'},ensure_ascii=False)}</script></head>
<body data-language="{lang}" data-assets="{a}"><a class="skip" href="#main">{esc(c['skip'])}</a>
<header class="site-header"><div class="wrap nav"><a class="brand" href="#main" aria-label="まち / machi"><img src="{a}icon.png" width="44" height="44" alt=""><b>まち<span>machi</span></b></a><nav class="nav-right" aria-label="Navigation"><a class="nav-link" href="#features">{esc(c['nav'][0])}</a><a class="nav-link" href="#support">{esc(c['nav'][1])}</a><label class="lang-wrap"><select id="language" aria-label="{esc(c['language'])}">{switch}</select></label><a class="nav-cta" href="{TF}">TestFlight ↗</a></nav></div></header>
<main id="main"><section class="wrap hero"><div class="hero-copy"><div class="eyebrow">{esc(c['eyebrow'])}</div><h1><span>{esc(c['hero'][0])}</span><span>{esc(c['hero'][1])}</span></h1><p class="hero-description">{esc(c['intro'])}</p><div class="actions">{button()}<a class="text-link" href="#features">{esc(c['explore'])} <span aria-hidden="true">↓</span></a></div><p class="compat">{esc(c['compat'])}</p></div>
<div class="hero-stage"><div class="stage-arch" aria-hidden="true"></div><div class="stage-orbit" aria-hidden="true"></div><div class="ticket-stamp" aria-hidden="true"><div class="number">まち</div><div class="stub">LIVE EVENT JOURNAL<br>NO. 001 — KEEP THIS</div></div><div class="stage-label" aria-hidden="true"><span>まち v1.0</span>Ready Steady Go!</div><div class="phone" role="tabpanel" id="screen-view" aria-labelledby="screen-tab-0"><img id="hero-screen" src="{a}screens/{lang}-01-calendar.jpg" width="1320" height="2868" alt="{esc(c['photoAlt'])} — {esc(c['tabs'][0])}" fetchpriority="high"></div><div class="screen-tabs" role="tablist" aria-label="{esc(c['nav'][0])}">{tabs}</div><p class="screen-caption" id="screen-caption" aria-live="polite">{esc(c['caps'][0])}</p><p class="demo-note">{esc(c['demo'])}</p></div></section>
<div class="ribbon"><div class="wrap ribbon-inner"><span>LIVE EVENT JOURNAL</span><span class="dot"></span><span>まち — machi</span><span class="dot extra"></span><span class="extra">PLANS / TICKETS / MEMORIES</span><span class="dot"></span><span>v1.0 · Ready Steady Go!</span></div></div>
<section class="wrap" id="features"><div class="section-head reveal"><div class="eyebrow">{c['sectionKicker']}</div><h2>{lines(c['sectionTitle'])}</h2></div><div class="feature-grid"><article class="feature feature-calendar reveal"><span class="index">01 / {esc(c['tabs'][0])}</span><h2>{lines(c['calendarTitle'])}</h2><p>{esc(c['calendarBody'])}</p><div class="feature-foot">{esc(c['calendarFoot'])}</div>{phone(1)}</article><article class="feature feature-wallet reveal"><span class="index">02 / {esc(c['tabs'][1])}</span><h2>{lines(c['walletTitle'])}</h2><p>{esc(c['walletBody'])}</p><div class="feature-foot">{esc(c['walletFoot'])}</div>{phone(2)}</article></div><article class="feature feature-archive reveal"><div><span class="index">03 / {esc(c['tabs'][2])}</span><h2>{lines(c['archiveTitle'])}</h2><p>{esc(c['archiveBody'])}</p><div class="feature-foot">{esc(c['archiveFoot'])}</div></div><div class="archive-stage">{phone(3)}</div></article><div class="two-notes"><article class="reveal"><div class="note-symbol" aria-hidden="true">✎</div><h2>{lines(c['personalTitle'])}</h2><p>{esc(c['personalBody'])}</p></article><article class="reveal"><div class="note-symbol" aria-hidden="true">↔</div><h2>{lines(c['syncTitle'])}</h2><p>{esc(c['syncBody'])}</p><div class="sync-pills">{''.join('<span>'+esc(x)+'</span>' for x in c['syncPills'])}</div></article></div></section>
<section class="download-section" id="download"><div class="reveal"><img class="brand-large" src="{a}icon.png" width="78" height="78" alt=""><div class="eyebrow">{c['closingKicker']}</div><h2>{lines(c['closingTitle'])}</h2><p>{esc(c['closingBody'])}</p>{button()}<div class="version">{esc(c['version'])}</div></div></section>
<section class="wrap support" id="support"><h2>{esc(c['stepsTitle'])}</h2><div class="steps">{steps}</div><div class="support-grid"><div><h2>{esc(c['supportTitle'])}</h2><div class="contact"><p>{esc(c['contact'])}</p><a href="https://github.com/Akisui/machi-web/issues">{esc(c["feedbackLink"])} ↗</a></div></div><div class="faq">{faq}</div></div></section></main><footer class="site-footer"><div class="wrap"><div class="footer-top"><span>© 2026 {esc(c['credit'])}</span><a href="https://akisui.github.io/machi-privacy/#{lang}">{esc(c['privacy'])} ↗</a></div><p class="data-note">{esc(c['dataNote'])}</p></div></footer><script type="application/json" id="screen-copy">{json.dumps({'captions':c['caps'],'alt':c['photoAlt'],'tabs':c['tabs']},ensure_ascii=False)}</script></body></html>'''
 out=R if root else R/lang;out.mkdir(exist_ok=True);(out/'index.html').write_text(page)
for lang in C:build(lang)
build('ja',True)
(R/'404.html').write_text('<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>まち — 404</title><style>body{font-family:system-ui;background:#faf9f6;color:#24343d;padding:12vw}a{color:#c83c53}</style><h1>まち</h1><p>ページが見つかりません / Page not found</p><a href="/machi-web/">Home →</a></html>')
(R/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n')
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+l+'/</loc></url>' for l in C)+'</urlset>')
(R/'.nojekyll').touch()
print('Generated five localized pages and language-aware entry.')
